package scp_candidate.Docking_Access_Supervisor

import org.sireum._
import art._
import scp_candidate._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@sig trait BerthCommitment_Api {
  def id: Art.BridgeId
  def berth_transition_evidence_Id : Art.PortId
  def prior_berth_state_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var prior_berth_state: Docking_Access_Supervisor.BerthState.Type = $

  def put_prior_berth_state(value : Docking_Access_Supervisor.BerthState.Type) : Unit = {
    Contract(
      Modifies(prior_berth_state),
      Ensures(
        prior_berth_state == value
      )
    )
    Spec {
      prior_berth_state = value
    }

    Art.putValue(prior_berth_state_Id, Docking_Access_Supervisor.BerthState_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class BerthCommitment_Initialization_Api (
  val id: Art.BridgeId,
  val berth_transition_evidence_Id : Art.PortId,
  val prior_berth_state_Id : Art.PortId) extends BerthCommitment_Api

@datatype class BerthCommitment_Operational_Api (
  val id: Art.BridgeId,
  val berth_transition_evidence_Id : Art.PortId,
  val prior_berth_state_Id : Art.PortId) extends BerthCommitment_Api {

  // Logika spec var representing port state for incoming data port
  @spec var berth_transition_evidence: Docking_Access_Supervisor.BerthTransitionEvidence = $

  def get_berth_transition_evidence() : Option[Docking_Access_Supervisor.BerthTransitionEvidence] = {
    Contract(
      Ensures(
        Res == Some(berth_transition_evidence)
      )
    )
    val value : Option[Docking_Access_Supervisor.BerthTransitionEvidence] = Art.getValue(berth_transition_evidence_Id) match {
      case Some(Docking_Access_Supervisor.BerthTransitionEvidence_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port berth_transition_evidence.  Expecting 'Docking_Access_Supervisor.BerthTransitionEvidence_Payload' but received ${v}")
        None[Docking_Access_Supervisor.BerthTransitionEvidence]()
      case _ => None[Docking_Access_Supervisor.BerthTransitionEvidence]()
    }
    return value
  }
}
